package com.networkmonitorpro.ui.adapter; import android.view.*;import android.widget.*;import androidx.recyclerview.widget.*;import com.networkmonitorpro.R;import com.networkmonitorpro.data.entity.DownloadHistory;import java.util.*; public class DownloadAdapter extends RecyclerView.Adapter<DownloadAdapter.VH>{ public interface Listener{void pause(DownloadHistory d);void resume(DownloadHistory d);void cancel(DownloadHistory d);} private List<DownloadHistory> data=new ArrayList<>(); private final Listener l; public DownloadAdapter(Listener l){this.l=l;} public void submit(List<DownloadHistory>d){data=d==null?new ArrayList<>():d;notifyDataSetChanged();} public VH onCreateViewHolder(ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_download,p,false));} public void onBindViewHolder(VH h,int p){DownloadHistory d=data.get(p);h.name.setText(d.fileName);h.progress.setProgress(d.progress);h.status.setText(d.status+" • "+d.speedBps/1024+" KB/s • "+d.category);h.pause.setOnClickListener(v->l.pause(d));h.resume.setOnClickListener(v->l.resume(d));h.cancel.setOnClickListener(v->l.cancel(d));} public int getItemCount(){return data.size();} static class VH extends RecyclerView.ViewHolder{TextView name,status;ProgressBar progress;Button pause,resume,cancel;VH(View v){super(v);name=v.findViewById(R.id.fileName);status=v.findViewById(R.id.status);progress=v.findViewById(R.id.progress);pause=v.findViewById(R.id.pause);resume=v.findViewById(R.id.resume);cancel=v.findViewById(R.id.cancel);}} }
